  3→import java.nio.charset.StandardCharsets;
  4→import java.util.Arrays;
  5→import java.util.List;
  6→
  7→import jlsm.table.EncryptionSpec;
  8→import jlsm.table.FieldDefinition;
  9→import jlsm.table.JlsmSchema;
